<map version="1.0.1"><node CREATED="1747229357230" ID="ID_root" MODIFIED="1747229357230" TEXT="数据结构重点"><node CREATED="1747229357230" ID="ID_8456c253a19e4c86" POSITION="right" MODIFIED="1747229357230" TEXT="线性表"><node CREATED="1747229357230" ID="ID_fc01216c232fb234" MODIFIED="1747229357230" TEXT="数组"><node CREATED="1747229357230" ID="ID_5e494036e2d62788" MODIFIED="1747229357230" TEXT="如果Vector有点难理解。&amp;nbsp;&amp;lt;br&amp;gt;那么对于普通长度的数组一定要掌握"><node CREATED="1747229357230" ID="ID_42d98317b9dbfeb2" MODIFIED="1747229357230" TEXT="其实Vector，就是做了两个事情。&amp;lt;br&amp;gt;1.底层的数组使用的是堆上的空间。&amp;nbsp;但是它的操作和数组基本一致。 arr[1]&amp;nbsp;都可以使用&amp;lt;br&amp;gt;2.数组一旦装不下，这时候可以扩容。&amp;nbsp;堆空间申请的内存，可以使用realloc扩容"></node><node CREATED="1747229357230" ID="ID_1d7515deec6eff8f" MODIFIED="1747229357230" TEXT="建议大家代码一定要自己写一下。如果不写代码，这个过程纯靠背顶不住"></node><node CREATED="1747229357230" ID="ID_63b119779ac1bf03" MODIFIED="1747229357230" TEXT="过程一定要知道，且能用自己的话描述出来！"></node></node><node CREATED="1747229357230" ID="ID_3e28ad39ac8a5cf2" MODIFIED="1747229357230" TEXT="往数组指定下标插入数据"><node CREATED="1747229357230" ID="ID_ca98ee7dadb1af5a" MODIFIED="1747229357230" TEXT="p[index]。&amp;lt;br&amp;gt;将index往后的数据，整体往后挪一位。然后将要插入的数据放在该下标"></node></node><node CREATED="1747229357230" ID="ID_336d344401b71ade" MODIFIED="1747229357230" TEXT="删除指定下标数据"></node><node CREATED="1747229357230" ID="ID_66b022e27d4c6fc6" MODIFIED="1747229357230" TEXT="修改指定下标数据"></node><node CREATED="1747229357230" ID="ID_d7ff27388ae7d495" MODIFIED="1747229357230" TEXT="查找数据是否存在"></node></node><node CREATED="1747229357230" ID="ID_c9e334f65606020b" MODIFIED="1747229357230" TEXT="链表"><node CREATED="1747229357230" ID="ID_7d468405682dd004" MODIFIED="1747229357230" TEXT="头插法插入数据、尾插法插入数据"></node><node CREATED="1747229357230" ID="ID_10d64ef3ac66723d" MODIFIED="1747229357230" TEXT="往指定下标插入数据数据，能掌握更好"><node CREATED="1747229357230" ID="ID_8b23d149e82095cd" MODIFIED="1747229357230" TEXT="一般面试的问法，就是，简单描述一下链表插入数据的流程"></node><node CREATED="1747229357230" ID="ID_b88cc35074ef7eea" MODIFIED="1747229357230" TEXT="在链表上插入一个数据，需要找到它的前驱结点&amp;lt;br&amp;gt;创建新结点，把数据存进去。&amp;lt;br&amp;gt;新结点的指针域，指向前驱结点的指针域。&amp;lt;br&amp;gt;前驱结点的指针域，再指向这个新结点"></node></node><node CREATED="1747229357230" ID="ID_64c794a140e6048c" MODIFIED="1747229357230" TEXT="删除一个链表上的结点，掌握最基本的。比如开天眼了，&amp;lt;br&amp;gt;给了你要删除数据的前一个结点，之后怎么删除下一个结点"><node CREATED="1747229357230" ID="ID_b30d1e228c2c9190" MODIFIED="1747229357230" TEXT="在面试的时候，回答大致就可以，比如使用临时指针存储一下待删除的。&amp;lt;br&amp;gt;然后将前一个指针的next域，存储待删除的next域&amp;lt;br&amp;gt;最后将待删除的结点释放就可以了。&amp;nbsp;不要纯背代码"></node><node CREATED="1747229357230" ID="ID_256e1f711465d6e4" MODIFIED="1747229357230" TEXT="不过自己写代码的时候，按照索引删建议掌握。因为可以锻炼自己的思维缜密性，&amp;lt;br&amp;gt;写多了这种比较缜密的代码，bug会少。"></node><node CREATED="1747229357230" ID="ID_3970312e92162409" MODIFIED="1747229357230" TEXT="删除指定索引的数据"></node><node CREATED="1747229357230" ID="ID_007ef1add860e1c1" MODIFIED="1747229357230" TEXT="删除指定数据"></node></node><node CREATED="1747229357230" ID="ID_2e57c9e416da2703" MODIFIED="1747229357230" TEXT="改某个索引的数据。这个比较简单"></node><node CREATED="1747229357230" ID="ID_7044c99869b2d386" MODIFIED="1747229357230" TEXT="查找某个数据，查找某个索引的数据"></node></node><node CREATED="1747229357230" ID="ID_b548f9f30982608c" MODIFIED="1747229357230" TEXT="关于这种，面试官喜欢对照问。&amp;nbsp;"><node CREATED="1747229357230" ID="ID_f25035bc30ff0ffd" MODIFIED="1747229357230" TEXT="比如，现在假设，这里有个数组，有个链表。&amp;nbsp;将它们的插入流程简单对比一下"></node><node CREATED="1747229357230" ID="ID_264ce58b97eb0aa5" MODIFIED="1747229357230" TEXT="比如删除流程"></node><node CREATED="1747229357230" ID="ID_e112c74c1822352f" MODIFIED="1747229357230" TEXT="一定要注意的是，能够用自己的话说出来流程"></node><node CREATED="1747229357230" ID="ID_26ba40e4bb2ce605" MODIFIED="1747229357230" TEXT="简单介绍一下线性表（减分项）&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;线性表，就是一个线性的数据结构。 数据是一个接着一个的。 在物理上，有两种组织方式，数组和链表。 数组的内存是连续的。链表的内存是离散的，主要是靠指针来指示下一个结点。&amp;lt;br&amp;gt;数组的查找是比较快的，插入和删除速度是比较慢的。 数组是有随机访问特点的，简单说，就是要访问第n个数据， 可以根据直接根据一个公式计算出来地址，然后去访问该地址。 base_addr+index*sizeof(int)&amp;lt;br&amp;gt;链表的插入，删除比较快。 查找是比较慢。"></node></node></node><node CREATED="1747229357230" ID="ID_6e5d124e2c6f310e" POSITION="right" MODIFIED="1747229357230" TEXT="栈&amp;amp;队列"><node CREATED="1747229357230" ID="ID_749623807ff5c516" MODIFIED="1747229357230" TEXT="要知道基础的概念：&amp;nbsp;什么是栈，什么是队列"></node><node CREATED="1747229357230" ID="ID_b51226d3cdb0a450" MODIFIED="1747229357230" TEXT="栈是操作受限的线性表，只允许从一端进出"><node CREATED="1747229357230" ID="ID_39cbb469a65b146f" MODIFIED="1747229357230" TEXT="数据后进先出"></node><node CREATED="1747229357230" ID="ID_d2098f9aaee61b29" MODIFIED="1747229357230" TEXT="栈用来存储函数调用过程"></node></node><node CREATED="1747229357230" ID="ID_a3e74ea2a8e6145f" MODIFIED="1747229357230" TEXT="队列是&amp;nbsp;只允许从一端进，从另外一端出"><node CREATED="1747229357230" ID="ID_b8f434504e5aba81" MODIFIED="1747229357230" TEXT="数据是先进先出"></node><node CREATED="1747229357230" ID="ID_566afd3ecfa91e4d" MODIFIED="1747229357230" TEXT="可以保证公平。先来的先出，可以保证数据先到的先处理"></node></node><node CREATED="1747229357230" ID="ID_0ba4c926d346e668" MODIFIED="1747229357230" TEXT="怎么实现的"><node CREATED="1747229357230" ID="ID_5aa31f79a024412a" MODIFIED="1747229357230" TEXT="使用数组"></node><node CREATED="1747229357230" ID="ID_646990adeffe0da1" MODIFIED="1747229357230" TEXT="使用链表"></node></node><node CREATED="1747229357230" ID="ID_5d7c80ec6656e2d0" MODIFIED="1747229357230" TEXT="栈的实现"><node CREATED="1747229357230" ID="ID_2ea3a3b15d420ae4" MODIFIED="1747229357230" TEXT="一个普通的数组，再额外加上一个int类型的变量&amp;lt;br&amp;gt;来存储栈顶的位置。&amp;nbsp;进栈的时候，将数据放进去，再将这个int类型的变量+1"></node><node CREATED="1747229357230" ID="ID_74e4880f3ef46274" MODIFIED="1747229357230" TEXT="栈使用链表实现，是类似的"></node></node><node CREATED="1747229357230" ID="ID_fc2dc25649c93302" MODIFIED="1747229357230" TEXT="队列的实现"><node CREATED="1747229357230" ID="ID_86b4dbf1a45091a6" MODIFIED="1747229357230" TEXT="线性表"></node><node CREATED="1747229357230" ID="ID_f1d4974e3fb4df57" MODIFIED="1747229357230" TEXT="使用链表来实现队列。&amp;nbsp;就是从尾进数据，尾插。从头出数据，"></node><node CREATED="1747229357230" ID="ID_9d9698fd6a16d39f" MODIFIED="1747229357230" TEXT="使用数组来实现。&amp;nbsp;循环队列的实现思路。&amp;nbsp;"></node><node CREATED="1747229357230" ID="ID_344157f10415ff25" MODIFIED="1747229357230" TEXT="什么是循环队列"><node CREATED="1747229357230" ID="ID_8d28669a7de73364" MODIFIED="1747229357230" TEXT="循环队列其实就是用数组的方式来实现队列。&amp;nbsp;&amp;lt;br&amp;gt;它就是用两个下标来标识开始和结尾的位置。在进出数据数据的时候，只需要挪动两个下标，不需要挪动数据。&amp;nbsp;&amp;lt;br&amp;gt;这种做法，如果光+1.这时候会出现假满问题。&amp;nbsp;这时候我们采用的手段是，将&amp;nbsp;下标+1后对长度取余。&amp;nbsp;这时候如果超过了length.&amp;lt;br&amp;gt;这时候会从index=0继续走。&amp;nbsp;这就是循环的概念。&amp;nbsp;"></node></node><node CREATED="1747229357230" ID="ID_426b1c5289c11835" MODIFIED="1747229357230" TEXT="循环队列的判空判满问题。&amp;nbsp;"><node CREATED="1747229357230" ID="ID_68b63af23bdc4402" MODIFIED="1747229357230" TEXT="size"></node><node CREATED="1747229357230" ID="ID_7809a2ad2a191f2a" MODIFIED="1747229357230" TEXT="如果满了。&amp;nbsp;扩容，循环队列能不能用realloc。&amp;lt;br&amp;gt;应该用 malloc ，然后将原始的数据拷贝过来。&amp;nbsp;从 front---&amp;gt;rear"></node></node></node></node><node CREATED="1747229357230" ID="ID_0c71333059a66158" POSITION="right" MODIFIED="1747229357230" TEXT="树"><node CREATED="1747229357230" ID="ID_b4f3af9bb45d25fe" MODIFIED="1747229357230" TEXT="要知道，什么是树"><node CREATED="1747229357230" ID="ID_34cfd6a4159ee282" MODIFIED="1747229357230" TEXT="struct node_s{&amp;lt;br&amp;gt;&amp;nbsp;int data;&amp;lt;br&amp;gt;&amp;nbsp;struct node_s&amp;nbsp; *left;&amp;lt;br&amp;gt;&amp;nbsp;struct node_s&amp;nbsp; *right;&amp;lt;br&amp;gt;}"></node></node><node CREATED="1747229357230" ID="ID_d7e7f9c1bddfdd82" MODIFIED="1747229357230" TEXT="要知道二叉搜索树是什么"></node><node CREATED="1747229357230" ID="ID_1c30482e00c1fb65" MODIFIED="1747229357230" TEXT="要知道二叉搜搜索树的优点在哪"><node CREATED="1747229357230" ID="ID_80cc9b311523bd96" MODIFIED="1747229357230" TEXT="查询的性能高。&amp;nbsp;但是是有前提的，这棵树应该不歪。&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229357230" ID="ID_1105da1dc707de12" MODIFIED="1747229357230" TEXT="红黑树是什么东西"><node CREATED="1747229357230" ID="ID_2212ec9c8397273f" MODIFIED="1747229357230" TEXT="就是一个特殊的二叉搜索树，有一些自己的平衡策略。&amp;nbsp;&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229357230" ID="ID_633e0a2cc50af504" MODIFIED="1747229357230" TEXT="二叉树的实现方式有几种"><node CREATED="1747229357230" ID="ID_e270498f1d7e1d5b" MODIFIED="1747229357230" TEXT="一个结点里面，有左右两个指针来实现的。&amp;nbsp;"></node><node CREATED="1747229357230" ID="ID_78c3b47ec9fdc7fd" MODIFIED="1747229357230" TEXT="和单链表很像。所以，操作很链表非常相似。&amp;nbsp;"></node><node CREATED="1747229357230" ID="ID_94f052f7aef3eafc" MODIFIED="1747229357230" TEXT="数组也可以模拟二叉树"><node CREATED="1747229357230" ID="ID_d313d7a71f02e3d8" MODIFIED="1747229357230" TEXT="一般数组模拟，要么是满二叉树，要么是完全二叉树。"></node><node CREATED="1747229357230" ID="ID_eaeb801be6d879c5" MODIFIED="1747229357230" TEXT="完全二叉树：&amp;nbsp;就是前面n-1层都是满的，最后一层，所有的结点都放在最左侧。&amp;nbsp;&amp;lt;br&amp;gt;"></node><node CREATED="1747229357230" ID="ID_734280cd6f3662c4" MODIFIED="1747229357230" TEXT="满二叉树：&amp;nbsp;每一层都是满的"></node></node><node CREATED="1747229357230" ID="ID_f4e2cd19395c3612" MODIFIED="1747229357230" TEXT="如果代码写不出来，基本的东西要知道"><node CREATED="1747229357230" ID="ID_7c4afac80d90de5e" MODIFIED="1747229357230" TEXT="什么是树、什么是二叉搜索树、什么是红黑树（作用是什么）。"></node><node CREATED="1747229357230" ID="ID_74050a206bcea8e4" MODIFIED="1747229357230" TEXT="添加的代码，查找的代码，都是比较简单的。&amp;nbsp;可以去尝试一下"></node><node CREATED="1747229357230" ID="ID_68aa1f7102dcd15e" MODIFIED="1747229357230" TEXT="删除的代码有点难度。不用管"></node><node CREATED="1747229357230" ID="ID_e8074822f7d6b671" MODIFIED="1747229357230" TEXT="扩展：B树、B+树，这些了解一下。优点，应用场景。&amp;nbsp;后期工作了之后可以花点时间学学"></node></node></node><node CREATED="1747229357230" ID="ID_0ed19ce7d5c77f1a" MODIFIED="1747229357230" TEXT="扩展一下"><node CREATED="1747229357230" ID="ID_52afd64dfafc1734" MODIFIED="1747229357230" TEXT="数据库。索引，采用是B+树。&amp;nbsp;&amp;nbsp;&amp;lt;br&amp;gt;"></node><node CREATED="1747229357230" ID="ID_cbefd426a92c4677" MODIFIED="1747229357230" TEXT="B树：每一层的孩子节点都多。&amp;nbsp;二叉树，一个结点最多两个。&amp;nbsp;&amp;lt;br&amp;gt;B树可能一层有1000个孩子。&amp;nbsp;相同层高下，能装的数据会非常多"><node CREATED="1747229357230" ID="ID_62231c90d5dcb7af" MODIFIED="1747229357230" TEXT="为什么降低树的高度有好处，因为树是存储在磁盘中。&amp;lt;br&amp;gt;树层高高，读磁盘的次数会多，磁盘的速度非常慢。所以导致了数据库的速度非常慢"></node><node CREATED="1747229357230" ID="ID_6669801450e257f3" MODIFIED="1747229357230" TEXT="如果对B树，四层能装多少数据？&amp;lt;br&amp;gt;1000*1000*1000 = 10亿"></node></node></node></node><node CREATED="1747229357230" ID="ID_dfceec48a6efa4e5" POSITION="right" MODIFIED="1747229357230" TEXT="哈希表"><node CREATED="1747229357230" ID="ID_767a81cb5e1ae84c" MODIFIED="1747229357230" TEXT="代码比较难。&amp;nbsp;建议大家理解一下代码，要写一下代码。&amp;lt;br&amp;gt;如果实在写不出来，重点应该是理解结构 +&amp;nbsp;添加流程。"></node><node CREATED="1747229357230" ID="ID_af217b6ca51a154d" MODIFIED="1747229357230" TEXT="结构和添加流程一定要记住"><node CREATED="1747229357230" ID="ID_4ba30a8a9110b205" MODIFIED="1747229357230" TEXT="1.简单说说你所认识的哈希表。&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;存储键值对的数据结构。 底层结构是数组+链表。&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;比如，现在要存储进去一个键值对。&amp;nbsp; &amp;lt;br&amp;gt;1.使用哈希函数，对这个key进行计算，得到一个int。 &amp;lt;br&amp;gt;2.使用得到的int，对数组长度进行取余。 之后其实这个键值对就像往这个下标存储&amp;lt;br&amp;gt;3.去该位置检查是否有数据。 如果没有数据，这时候直接将数据存进去。 &amp;lt;br&amp;gt;如果这个位置有数据。 挨个比较，键是否相同。 如果键不相同，这时候比较下一个； 键相同，用新值覆盖旧值；"></node><node CREATED="1747229357230" ID="ID_4b950f6239fb4556" MODIFIED="1747229357230" TEXT="底层结构就是数组+链表"></node><node CREATED="1747229357230" ID="ID_48ed09ffb708e2e2" MODIFIED="1747229357230" TEXT="常见的面试题基本都一个回答思路"><node CREATED="1747229357230" ID="ID_8c8c9e55c1a303a8" MODIFIED="1747229357230" TEXT="1.哈希表效率为啥高：&amp;nbsp;其实就是让你说底层结构 +&amp;nbsp;添加流程"></node><node CREATED="1747229357230" ID="ID_2fae4893d75cc958" MODIFIED="1747229357230" TEXT="2.为啥哈希表底层结构是数组+链表"></node><node CREATED="1747229357230" ID="ID_d98a3d7bd170474c" MODIFIED="1747229357230" TEXT="3.哈希表底层结构是啥"></node><node CREATED="1747229357230" ID="ID_ecce337a2534e556" MODIFIED="1747229357230" TEXT="要听懂面试官的问题。&amp;nbsp;碰到自己会说的多说点。&amp;nbsp;&amp;lt;br&amp;gt;往自己懂的上面聊"></node></node></node><node CREATED="1747229357230" ID="ID_4b6a822e095a6cea" MODIFIED="1747229357230" TEXT="代码一定要掌握的"><node CREATED="1747229357230" ID="ID_65651f9180607463" MODIFIED="1747229357230" TEXT="添加的代码"></node><node CREATED="1747229357230" ID="ID_6feed9fba50c52ec" MODIFIED="1747229357230" TEXT="查找的代码"></node><node CREATED="1747229357230" ID="ID_2801d0e67e4fd728" MODIFIED="1747229357230" TEXT="删除"><node CREATED="1747229357230" ID="ID_079ad04b578898b0" MODIFIED="1747229357230" TEXT="如果能掌握就掌握。如果掌握不了，就先放一下。&amp;nbsp;"></node><node CREATED="1747229357230" ID="ID_3b0b05291d9c01a7" MODIFIED="1747229357230" TEXT="如果会了添加和查找，&amp;nbsp;对于删除的大致逻辑是没问题的。&amp;nbsp;但是对于它的指针挪动确实有点复杂"></node></node></node><node CREATED="1747229357230" ID="ID_423fafc998772b7e" MODIFIED="1747229357230" TEXT="加载因子"><node CREATED="1747229357230" ID="ID_9562013a5ba9f026" MODIFIED="1747229357230" TEXT="就是用来评判哈希表数据稀疏程度的。&amp;nbsp;&amp;lt;br&amp;gt;键值对数目 /&amp;nbsp;数组长度。&amp;nbsp;&amp;lt;br&amp;gt;&amp;lt;br&amp;gt;5/10&amp;nbsp; &amp;nbsp; 10/10&amp;lt;br&amp;gt;1000 / 10"></node><node CREATED="1747229357230" ID="ID_a1088d7f6b4974e0" MODIFIED="1747229357230" TEXT="加载因子越大。 trade off&amp;lt;br&amp;gt;能装更多的数据，但是效率受到了影响。&amp;lt;br&amp;gt;如果加载因子超过了一定的数值，&amp;nbsp;&amp;nbsp;"></node><node CREATED="1747229357230" ID="ID_6e4374b54fe54934" MODIFIED="1747229357230" TEXT="实践过程中，一般采用的是一个阈值。&amp;nbsp; 3/4&amp;lt;br&amp;gt;"></node></node><node CREATED="1747229357230" ID="ID_c4f6d8af131ca081" MODIFIED="1747229357230" TEXT="对于传统的数组的添加、查找流程。代码一定要掌握。&amp;lt;br&amp;gt;如果删除能掌握更好"></node><node CREATED="1747229357230" ID="ID_dac210d067b1c29e" MODIFIED="1747229357230" TEXT="对于动态的数组，建议了解一下。&amp;nbsp;在面试的时候，被问到数据量太多的时候，效率低咋办。&amp;lt;br&amp;gt;知道有扩容这个动作在这里可以保证效率就可以了。&amp;nbsp;"></node></node></node></map>